import time

def retry_with_backoff(fn, max_attempts=3):
    """
    Call `fn` up to `max_attempts` times. If it succeeds, return its result.
    If it fails on the last attempt, re‑raise the exception without sleeping.
    """
    for attempt in range(max_attempts):
        try:
            return fn()
        except Exception:
            # If this was the last allowed attempt, re‑raise immediately.
            if attempt == max_attempts - 1:
                raise
            # Otherwise wait a little before retrying.
            time.sleep(0.01 * (attempt + 1))
