def parse_bool(value):
    """
    Parse a value into a boolean.

    Accepts bool, int, and str. True/1/'true'/'yes'/'1' (case‑insensitive) are True;
    False/0/'false'/'no'/'0' are False. Any other string raises ValueError.
    """
    if isinstance(value, bool):
        return value

    if isinstance(value, int):
        if value == 1:
            return True
        if value == 0:
            return False
        raise ValueError(f"Invalid integer for boolean conversion: {value}")

    if isinstance(value, str):
        val = value.strip().lower()
        if val in {"true", "yes", "1"}:
            return True
        if val in {"false", "no", "0"}:
            return False
        raise ValueError(f"Invalid string for boolean conversion: {value}")

    raise TypeError(f"Unsupported type for boolean conversion: {type(value).__name__}")
